mapper.select:
SELECT COUNT(DISTINCT session_id) FROM chat_messages
WHERE sender_type = 'AGENT' AND sender_id = #{agentId}
AND create_time BETWEEN #{start} AND #{end}

SELECT AVG(GREATEST(0, TIMESTAMPDIFF(SECOND, transfer_time, first_agent_msg))) FROM (
    SELECT a.session_id,
        (SELECT MIN(create_time) FROM chat_messages
         WHERE session_id = a.session_id AND sender_type = 'SYSTEM') AS transfer_time,
        a.first_agent_msg
    FROM (
        SELECT session_id, MIN(create_time) AS first_agent_msg
        FROM chat_messages WHERE sender_type = 'AGENT' AND sender_id = #{agentId}
        AND create_time BETWEEN #{start} AND #{end}
        GROUP BY session_id
    ) a
) t WHERE t.transfer_time IS NOT NULL

SELECT DATE(create_time) AS statDate, COUNT(DISTINCT session_id) AS totalCount
FROM chat_messages WHERE sender_type = 'AGENT' AND sender_id = #{agentId}
AND create_time BETWEEN #{start} AND #{end}
GROUP BY DATE(create_time) ORDER BY statDate

SELECT COUNT(*) FROM (
    SELECT a.session_id,
        TIMESTAMPDIFF(SECOND,
            (SELECT MIN(create_time) FROM chat_messages WHERE session_id = a.session_id AND sender_type = 'USER'),
            a.first_agent_msg
        ) AS response_seconds
    FROM (
        SELECT session_id, MIN(create_time) AS first_agent_msg
        FROM chat_messages WHERE sender_type = 'AGENT' AND sender_id = #{agentId}
        AND create_time BETWEEN #{start} AND #{end}
        GROUP BY session_id
    ) a
) t WHERE t.response_seconds IS NOT NULL AND t.response_seconds <= #{slaThresholdSeconds}

mapper.update:
UPDATE chat_messages SET satisfaction = #{satisfaction}
WHERE session_id = #{sessionId}
AND sender_type = 'AGENT'
AND message_seq = (
    SELECT max_seq FROM (
        SELECT MAX(message_seq) AS max_seq FROM chat_messages
        WHERE session_id = #{sessionId} AND sender_type = 'AGENT'
    ) t
)
LIMIT 1

