SELECT AVG(satisfaction) FROM chat_messages
WHERE sender_type = 'AGENT' AND sender_id = #{agentId}
AND satisfaction IS NOT NULL
AND create_time BETWEEN #{start} AND #{end}

SELECT COUNT(DISTINCT sender_id) FROM chat_messages
WHERE sender_type = 'AGENT'
AND create_time BETWEEN #{start} AND #{end}
